import{_ as n,a0 as a,w as r,s as d,ao as p,I as i,x as e,a1 as o,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"跟踪多个 Git 远程仓库 | LCTT x X-CMD","titleTemplate":false,"description":"跟踪多个 Git 远程仓库 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"跟踪多个 Git 远程仓库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"跟踪多个 Git 远程仓库 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201125 Keep track of multiple Git remote repositories","title":"跟踪多个 Git 远程仓库","tag":"202012","desc":""},"relativePath":"202012/20201125 Keep track of multiple Git remote repositories.md","filePath":"[post].md"}'),u={name:"202012/20201125 Keep track of multiple Git remote repositories.md"};function g(m,t,b,k,f,h){const s=a("Link");return r(),d("div",null,[t[30]||(t[30]=p('<h1 id="跟踪多个-git-远程仓库" tabindex="-1">跟踪多个 Git 远程仓库 <a class="header-anchor" href="#跟踪多个-git-远程仓库" aria-label="Permalink to “跟踪多个 Git 远程仓库”">​</a></h1><blockquote><p>拥有一致的命名标准是保持本地和上游 Git 仓库保持一致的关键。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/11/220828tjt9qlpmg1opvibq.jpg" alt=""></p><p>当本地 Git 仓库的命名与远程仓库不一致时，与远程仓库协作就会变得很混乱。</p><p>解决此问题的一个方法是标准化两个词的使用和含义：<code>origin</code> 指的是你个人的 <code>example.com/&lt;USER&gt;/*</code> 仓库，而 <code>upstream</code> 指的是你从 <code>origin</code> 仓库<ruby>复刻<rt>fork</rt></ruby>出来的 <code>example.com</code> 仓库。换句话说，<code>upstream</code> 指的是公开提交工作的上游仓库，而 <code>origin</code> 指的是你对上游仓库的本地复刻，例如，你从这里生成<ruby>拉取请求<rt>pull request</rt></ruby>（PR）。</p>',5)),i("p",null,[t[1]||(t[1]=e("以 ",-1)),o(s,{href:"https://github.com/distributed-system-analysis/pbench"},{default:l(()=>[...t[0]||(t[0]=[e("pbench",-1)])]),_:1}),t[2]||(t[2]=e(" 仓库为例，下面是一个逐步建立新的本地克隆的方法，其中 ",-1)),t[3]||(t[3]=i("code",null,"origin",-1)),t[4]||(t[4]=e(" 和 ",-1)),t[5]||(t[5]=i("code",null,"upstream",-1)),t[6]||(t[6]=e(" 的定义是一致的。",-1))]),t[31]||(t[31]=i("p",null,"1、在大多数 Git 托管服务上，当你想在上面工作时，必须对它进行复刻。当你运行自己的 Git 服务器时，这并不是必要的，但对于一个公开的代码库来说，这是一个在贡献者之间传输差异的简单方法。",-1)),t[32]||(t[32]=i("p",null,[e("创建一个 Git 仓库的复刻。在这个例子中，假设你的复刻位于 "),i("code",null,"example.com/<USER>/pbench"),e("。")],-1)),i("p",null,[t[8]||(t[8]=e("2、接下来，你必须获得一个统一资源标识符 （",-1)),o(s,{href:"https://en.wikipedia.org/wiki/Uniform_Resource_Identifier"},{default:l(()=>[...t[7]||(t[7]=[e("URI",-1)])]),_:1}),t[9]||(t[9]=e("），以便通过 SSH 进行",-1)),t[10]||(t[10]=i("ruby",null,[e("克隆"),i("rt",null,"cloning")],-1)),t[11]||(t[11]=e("。在大多数 Git 托管服务上，比如 GitLab 或 GitHub，它在一个标有 “Clone” 或 “Clone over SSH” 的按钮或面板上，可以将克隆 URI 复制到剪贴板中。",-1))]),t[33]||(t[33]=p(`<p>3、在你的开发系统中，使用你复制的 URI 克隆仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone git@example.com:&lt;USER&gt;/pbench.git</span></span></code></pre></div><p>这将以默认名称 <code>origin</code> 来克隆 Git 仓库，作为你的 <code>pbench</code> 仓库复刻副本。</p><p>4、切换到刚才克隆的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/pbench</span></span></code></pre></div><p>5、下一步，获取源仓库的 SSH URI（你最初复刻的那个）。这可能和上面的方法一样。找到 “Clone” 按钮或面板，复制克隆地址。在软件开发中，这通常被称为“上游”，因为（理论上）这是大多数提交发生的地方，而你打算让这些提交流向下游的仓库。</p><p>6、将 URI 添加到你的本地仓库中。是的，将有<em>两个不同</em>的远程仓库分配给你的本地仓库副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add upstream git@example.com:bigproject/pbench.git</span></span></code></pre></div><p>7、现在你有两个命名远程仓库：<code>origin</code> 和 <code>upstream</code>。 你可以用 <code>remote</code> 子命令查看你的远程仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote -v</span></span></code></pre></div><p>现在，你的本地 <code>master</code> 分支正在跟踪 <code>origin</code> 的 <code>master</code>，这不一定是你想要的。你可能想跟踪这个分支的 <code>upstream</code> 版本，因为大多数开发都在上游进行。这个想法是，你要在从上游获得的内容的基础上添加更改。</p><p>8、将你的本地的 <code>master</code> 分支改成跟踪 <code>upstream/master</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git fetch upstream</span></span>
<span class="line"><span>$ git branch --set-upstream-to=upstream/master master</span></span></code></pre></div><p>你可以对任何你想要的分支这样做，而不仅仅是 <code>master</code>。例如，有些项目使用 <code>dev</code> 分支来处理所有不稳定的变化，而将 <code>master</code> 保留给已批准发布的代码。</p><p>9、一旦你设置了你的跟踪分支，一定要变基（<code>rebase</code>）你的 <code>master</code> 分支，使它与上游仓库的任何新变化保持一致：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote update</span></span>
<span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git rebase</span></span></code></pre></div>`,16)),i("p",null,[t[13]||(t[13]=e("这是一个保持 Git 仓库在不同复刻之间同步的好方法。如果你想自动完成这项工作，请阅读 Seth Kenlon 关于",-1)),o(s,{href:"https://opensource.com/article/19/11/how-host-github-gitlab-ansible"},{default:l(()=>[...t[12]||(t[12]=[e("使用 Ansible 托管 Git 仓库",-1)])]),_:1}),t[14]||(t[14]=e("的文章。",-1))]),t[34]||(t[34]=i("hr",null,null,-1)),i("p",null,[t[16]||(t[16]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/20/11/multiple-git-repositories"},{default:l(()=>[...t[15]||(t[15]=[e("https://opensource.com/article/20/11/multiple-git-repositories",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/portante"},{default:l(()=>[...t[17]||(t[17]=[e("Peter Portante",-1)])]),_:1}),t[22]||(t[22]=e(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[18]||(t[18]=[e("lujun9972",-1)])]),_:1}),t[23]||(t[23]=e(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[19]||(t[19]=[e("geekpi",-1)])]),_:1}),t[24]||(t[24]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[20]||(t[20]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[27]||(t[27]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[25]||(t[25]=[e("LCTT",-1)])]),_:1}),t[28]||(t[28]=e(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:l(()=>[...t[26]||(t[26]=[e("Linux中国",-1)])]),_:1}),t[29]||(t[29]=e(" 荣誉推出",-1))])])}const y=n(u,[["render",g]]);export{T as __pageData,y as default};
